import { currentUser } from "@clerk/nextjs/server";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

const users: User[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

export async function listUsers(): Promise<User[]> {
  return users;
}

export async function getUser(id: string): Promise<User | undefined> {
  return users.find((u) => u.id === id);
}

// The shape we need from a Clerk user, kept narrow so this file doesn't
// depend on Clerk's full SDK types.
type ClerkUser = {
  id: string;
  firstName: string | null;
  username: string | null;
  emailAddresses: { emailAddress: string }[];
};

// Mirrors the signed-in Clerk user into the local user store, keyed by
// Clerk's user id. Creates an entry the first time we see them, and keeps
// name/email up to date on later calls.
function syncClerkUser(clerkUser: ClerkUser): User {
  const email = clerkUser.emailAddresses[0]?.emailAddress ?? "";
  const name =
    clerkUser.firstName ?? clerkUser.username ?? email.split("@")[0] ?? "User";

  const existing = users.find((u) => u.id === clerkUser.id);
  if (existing) {
    existing.email = email;
    existing.name = name;
    return existing;
  }

  const created: User = {
    id: clerkUser.id,
    email,
    name,
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(created);
  return created;
}

// Reads the signed-in user from Clerk (via the request's session) and syncs
// it into the local store. Returns undefined when nobody is signed in.
export async function getCurrentUser(): Promise<User | undefined> {
  const clerkUser = await currentUser();
  if (!clerkUser) return undefined;
  return syncClerkUser(clerkUser);
}

