export const metadata: Metadata = {
  title: "Notely",
  description: "Notely",
};

export default function RootLayout({ children }: LayoutProps<"/">) {
  return (
    <ClerkProvider>
      <html
        lang="en"
        className={`${geistSans.variable} ${geistMono.variable} h-full antialiased`}
      >
        <body className="min-h-full flex flex-col">
          <header className="flex items-center justify-between border-b border-black/[.08] px-6 py-3 dark:border-white/[.145]">
            <a href="/" className="font-semibold">
              Notely
            </a>
            <div className="flex items-center gap-3">
              <SignedOut>
                <SignInButton mode="modal">
                  <button className="text-sm font-medium">Sign in</button>
                </SignInButton>
                <SignUpButton mode="modal">
                  <button className="rounded-full bg-foreground px-4 py-1.5 text-sm font-medium text-background">
                    Sign up
                  </button>
                </SignUpButton>
              </SignedOut>
              <SignedIn>
                <a href="/dashboard" className="text-sm font-medium">
                  Dashboard
                </a>
                <UserButton afterSignOutUrl="/" />
              </SignedIn>
            </div>
          </header>
          <div className="flex flex-1 flex-col">{children}</div>
        </body>
      </html>
    </ClerkProvider>
  );
}

